var n=`0627-shorba-libiya`;var t=`world-0627`;var a=`LY`;var s=`northern-africa`;var o=4;var r=63;var l={en:`Shorba Libiya`,ua:`Лівійська шорба`};var g={en:`Shorba Libiya is a Libya classic prepared with lamb, yellow onion, tomato paste, vermicelli pasta. A measured home-style version, with ingredients assigned to the cooking steps where they are used.`,ua:`Лівійська шорба, страва кухні країни Лівія зі складниками: ягнятина, жовта цибуля, томатна паста, вермішель. Домашній рецепт із кількостями, прив’язаними до відповідних етапів приготування.`};var m=[{en:`Chop the vegetables as needed. Sauté the listed ingredients over medium heat, stirring, for about 11 minutes until softened and aromatic.`,ua:`Наріжте овочі за потреби. Пасеруйте зазначені складники на середньому вогні, помішуючи, приблизно 11 хвилин до м’якості й аромату.`,t:[`chopping`,`sauteing`],m:11,i:[[`lamb`,340,`g`],[`yellow-onion`,190,`g`],[`extra-virgin-olive-oil`,40,`ml`],[`tomato-paste`,40,`g`]]},{en:`Combine the remaining ingredients, cover partly and stew gently for about 48 minutes until the flavors meld and everything is tender.`,ua:`З’єднайте решту складників, частково накрийте й тушкуйте приблизно 48 хвилин до поєднання смаків і м’якості продуктів.`,t:[`stewing`],m:48,i:[[`chicken-stock`,900,`ml`],[`vermicelli-pasta`,100,`g`],[`canned-chickpeas`,190,`g`],[`ground-turmeric`,4,`g`],[`ground-cinnamon`,3,`g`]]},{en:`Finish with the listed ingredients, check seasoning and serve immediately.`,ua:`Додайте завершальні складники, перевірте смак і відразу подавайте.`,t:[`seasoning`,`garnishing`],m:4,i:[[`parsley`,20,`g`],[`lemon-juice`,30,`ml`]]}];var d={slug:n,id:t,country:`LY`,region:s,servings:4,minutes:63,title:l,text:g,steps:m};export{a as country,d as default,t as id,r as minutes,s as region,o as servings,n as slug,m as steps,g as text,l as title};